search_inference_docs.raw_response:
[
  {
    "criterion_id": "find_docs_succeeded",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_docs"
  },
  {
    "criterion_id": "find_examples_succeeded",
    "kind": "tool_call_succeeded",
    "required": false,
    "tool_name": "find_examples"
  },
  {
    "criterion_id": "results_contain_inference",
    "kind": "predicate",
    "required": true,
    "expression": "any('inference' in str(r).lower() for r in obs['tool_results'])"
  },
  {
    "criterion_id": "results_contain_endpoints",
    "kind": "predicate",
    "required": true,
    "expression": "any('endpoint' in str(r).lower() for r in obs['tool_results'])"
  },
  {
    "criterion_id": "documentation_content_found",
    "kind": "predicate",
    "required": true,
    "expression": "any(len(str(r)) > 50 and ('doc' in str(r).lower() or 'api' in str(r).lower() or 'guide' in str(r).lower()) for r in obs['tool_results'])"
  }
]

metric_drive_loss.raw_response:
[
  {
    "criterion_id": "val_loss_below_threshold",
    "kind": "metric_threshold",
    "required": true,
    "metric": "metrics.val_loss",
    "op": "<",
    "target": 0.1
  },
  {
    "criterion_id": "find_examples_succeeded",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_examples"
  },
  {
    "criterion_id": "no_errors",
    "kind": "predicate",
    "required": false,
    "expression": "len(obs.get('errors', [])) == 0"
  },
  {
    "criterion_id": "val_loss_metric_exists",
    "kind": "predicate",
    "required": false,
    "expression": "any(k == 'val_loss' for k in obs['metrics'].keys())"
  },
  {
    "criterion_id": "tool_results_present",
    "kind": "predicate",
    "required": false,
    "expression": "len(obs['tool_results']) > 0"
  }
]
